for(const [locale,entries] of Object.entries({"en":{"founder.art":"Rooted in Sudan. Built with people.","founder.note":"SIRAI brings together local insight, practical ideas and a belief that even small efforts can matter.","founder.chip1":"People first","founder.chip2":"Practical action","founder.chip3":"Local leadership"},"ar":{"founder.art":"جذورنا في السودان. ونبنيها مع الناس.","founder.note":"تجمع SIRAI بين الخبرة المحلية والأفكار العملية والإيمان بأن حتى الجهود الصغيرة يمكن أن تصنع فرقًا.","founder.chip1":"الناس أولًا","founder.chip2":"عمل عملي","founder.chip3":"القيادة المحلية"},"fr":{"founder.art":"Ancrés au Soudan. Construits avec les gens.","founder.note":"SIRAI réunit les savoirs locaux, les idées concrètes et la conviction que même de petits efforts peuvent compter.","founder.chip1":"Les personnes d’abord","founder.chip2":"Actions concrètes","founder.chip3":"Leadership local"},"de":{"founder.art":"Im Sudan verwurzelt. Gemeinsam mit Menschen gestaltet.","founder.note":"SIRAI verbindet lokales Wissen, praktische Ideen und die Überzeugung, dass selbst kleine Beiträge etwas bewirken können.","founder.chip1":"Menschen zuerst","founder.chip2":"Praktisches Handeln","founder.chip3":"Lokale Verantwortung"}})){Object.assign(strings[locale],entries)}
