for(const [locale,entries] of Object.entries({"en":{"nav.energy":"Energy toolkit","resource.3.kicker":"THIRD RESOURCE · ENERGY PLANNING","resource.3.title":"TaqaWise. Understand your energy.","resource.3.text":"A free household electricity toolkit for understanding appliance consumption, planning essential battery backup and exploring preliminary solar scenarios.","resource.3.cta":"Explore TaqaWise →"},"ar":{"nav.energy":"أداة الطاقة","resource.3.kicker":"المورد الثالث · تخطيط الطاقة","resource.3.title":"TaqaWise. افهم استهلاكك للطاقة.","resource.3.text":"أداة مجانية للمنازل تساعد على فهم استهلاك الأجهزة والتخطيط للطاقة الاحتياطية الأساسية واستكشاف خيارات أولية للطاقة الشمسية.","resource.3.cta":"استكشف TaqaWise ←"},"fr":{"nav.energy":"Outil énergie","resource.3.kicker":"TROISIÈME RESSOURCE · PLANIFICATION ÉNERGÉTIQUE","resource.3.title":"TaqaWise. Comprendre son énergie.","resource.3.text":"Un outil gratuit pour estimer la consommation des appareils domestiques, les besoins essentiels en batterie et des scénarios solaires préliminaires.","resource.3.cta":"Découvrir TaqaWise →"},"de":{"nav.energy":"Energie-Tool","resource.3.kicker":"DRITTE RESSOURCE · ENERGIEPLANUNG","resource.3.title":"TaqaWise. Energie verstehen.","resource.3.text":"Ein kostenloses Werkzeug zur Abschätzung des Stromverbrauchs, wichtiger Notstromlasten und erster Solarszenarien.","resource.3.cta":"TaqaWise entdecken →"}})){Object.assign(strings[locale],entries)}
